"""The message object of Anthropic's Messages API."""

from __future__ import annotations

from typing import Annotated, Any, Literal

from pydantic import Discriminator, Field, Tag

from ai_api.types.base import BaseAPIType
from ai_api.types.unknown import UNKNOWN, BaseUnknown, by_type


class TextBlock(BaseAPIType):
    """Text generated by the model.

    Attributes:
        type: Always ``"text"``.
        text: The text.
        citations: Citations supporting the text, as sent, if any.
    """

    type: Literal["text"] = "text"
    text: str
    citations: list[dict[str, Any]] | None = None


class UnknownBlock(BaseUnknown):
    """A content block of a type the library does not model yet.

    Thinking, tool use, server tool results and every block Anthropic
    adds later arrive as this, with all their fields as extra fields.
    """


type ContentBlock = Annotated[
    Annotated[TextBlock, Tag("text")] | Annotated[UnknownBlock, Tag(UNKNOWN)],
    Discriminator(by_type({"text": "text"})),
]
"""A content block of a message, told apart by ``type``."""


class StopDetails(BaseAPIType):
    """Why the output stopped, when ``stop_reason`` has more to say.

    Attributes:
        type: Kind of detail, such as ``"refusal"``.
        category: Policy category of a refusal, if named.
        explanation: Human-readable explanation, if available.
    """

    type: str
    category: str | None = None
    explanation: str | None = None


class Usage(BaseAPIType):
    """Token counts of a message.

    The total input is ``input_tokens`` plus both cache counts.

    Attributes:
        input_tokens: Input tokens not read from or written to the cache.
        output_tokens: Generated tokens.
        cache_creation_input_tokens: Input tokens written to the cache.
        cache_read_input_tokens: Input tokens read from the cache.
    """

    input_tokens: int
    output_tokens: int
    cache_creation_input_tokens: int | None = None
    cache_read_input_tokens: int | None = None


class Message(BaseAPIType):
    """A message generated by the model.

    Only the fields needed for text generation are modeled; the rest
    (``container``, ``diagnostics``, ...) are ignored.

    Attributes:
        id: Message identifier.
        type: Always ``"message"``.
        role: Always ``"assistant"``.
        model: Model that generated the message.
        content: Generated content blocks.
        stop_reason: Why generation stopped, such as ``"end_turn"`` or
            ``"max_tokens"``; ``None`` only in ``message_start``.
        stop_sequence: The custom stop sequence that was generated, if
            any.
        stop_details: More about the stop, such as a refusal's category.
        usage: Token counts.
    """

    id: str
    type: Literal["message"] = "message"
    role: Literal["assistant"] = "assistant"
    model: str
    content: list[ContentBlock] = Field(default_factory=list)
    stop_reason: str | None = None
    stop_sequence: str | None = None
    stop_details: StopDetails | None = None
    usage: Usage

    @property
    def text(self) -> str | None:
        """Join the text of the message.

        Returns:
            The text of all ``text`` blocks, or ``None`` if there are
            none.
        """
        texts = [
            block.text
            for block in self.content
            if isinstance(block, TextBlock)
        ]
        return "".join(texts) if texts else None
